{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 12,
      "verse": 1,
      "text_ar": "وَحَدَثَ بَيْنَمَا كَانَ الأَسَدُ يَتَكَلَّمُ بِهَذِهِ الكَلِمَاتِ مَعَ النَّسْرِ، أَنِّي رَأَيْتُ،",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 2,
      "text_ar": "وَهُوَذَا الرَّأْسُ الَّذِي بَقِيَ قَدِ اختَفَى، وَالجَنَاحَانِ اللَّذَانِ انْتَقَلا إِلَيْهِ قَامَا وَنَصَبَا نَفْسَيْهِمَا لِلْمُلْكِ؛ وَكَانَتْ مَمْلَكَتُهُمَا قَصِيرَةً وَمَلِيئَةً بِالصَّخَبِ.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 3,
      "text_ar": "رَأَيْتُ وَهُوَذَا هُمَا اختَفَيَا، وَاحْتَرَقَ جَسَدُ النَّسْرِ كُلُّهُ، حَتَّى كَانَتِ الأَرْضُ فِي خَوْفٍ عَظِيمٍ. ثُمَّ استَيْقَظْتُ بِسَبَبِ الحَيْرَةِ الشَّدِيدَةِ فِي عَقْلِي وَالخَوْفِ العَظِيمِ، وَقُلْتُ لِرُوحِي:",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 4,
      "text_ar": "«هُوَذَا أَنْتِ فَعَلْتِ هَذَا بِي، لأَنَّكِ تَفْحَصِينَ طُرُقَ العَلِيِّ.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 5,
      "text_ar": "هُوَذَا أَنَا لَازِلْتُ مُتْعَبًا فِي عَقْلِي، وَضَعِيفًا جِدًّا فِي رُوحِي. وَلَيْسَ فِيَّ وَلَوْ قُوَّةٌ قَلِيلَةٌ، بِسَبَبِ الخَوْفِ العَظِيمِ الَّذِي رُعِبْتُ بِهِ اللَّيْلَةَ.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 6,
      "text_ar": "لِذَلِكَ سَأَطْلُبُ الآنَ مِنَ العَلِيِّ أَنْ يُقَوِّيَنِي إِلَى النِّهَايَةِ».",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 7,
      "text_ar": "ثُمَّ قُلْتُ: «أَيُّهَا السَّيِّدُ الرَّبُّ، إِنْ كُنْتُ قَدْ وَجَدْتُ نِعْمَةً فِي عَيْنَيْكَ، وَإِنْ كُنْتُ مُبَرَّراً عِنْدَكَ أَكْثَرَ مِنْ كَثِيرِينَ غَيْرِي، وَإِنْ كَانَتْ صَلَاتِي قَدِ صَعِدَتْ حَقّاً أَمَامَ وَجْهِكَ،",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 8,
      "text_ar": "فَقَوِّنِي إِذاً، وَأَهِرْنِي أَنَا خَادِمَكَ، تَفْسِيرَ وَمَعْنَى هَذِهِ الرُّؤْيَا المُرْعِبَةِ الوَاضِحَ، لِكَيْ تُعَزِّيَ نَفْسِي تَمَاماً.",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 9,
      "text_ar": "لأَنَّكَ حَسِبْتَنِي أَهْلاً لِأَنْ تُرِيَنِي نِهَايَةَ الزَّمَانِ وَالأَحْدَاثَ الأَخِيرَةَ مِنَ الأَزْمِنَةِ».",
      "review_notes_ar": []
    },
    {
      "chapter": 12,
      "verse": 10,
      "text_ar": "فَقَالَ لِي: «هَذَا هُوَ تَفْسِيرُ هَذِهِ الرُّؤْيَا الَّتِي رَأَيْتَهَا:",
      "review_notes_ar": []
    }
  ]
}
